                comp.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w
                            and grid[nx][ny] == 1 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append(comp)

    inner_cells = set()
    halo_cells = set()

    for comp in components:
        rmin = min(r for r, c in comp)
        rmax = max(r for r, c in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)

        # Flood from a one-cell padded bounding box, treating only this
        # component as a wall. Unreached cells inside it are enclosed.
        lo_r, hi_r = max(0, rmin - 1), min(h - 1, rmax + 1)
        lo_c, hi_c = max(0, cmin - 1), min(w - 1, cmax + 1)
        exterior = set()
        stack = []
        for rr in range(lo_r, hi_r + 1):
            for cc in (lo_c, hi_c):
                if (rr, cc) not in comp and (rr, cc) not in exterior:
                    exterior.add((rr, cc))
                    stack.append((rr, cc))
        for cc in range(lo_c, hi_c + 1):
            for rr in (lo_r, hi_r):
                if (rr, cc) not in comp and (rr, cc) not in exterior:
                    exterior.add((rr, cc))
                    stack.append((rr, cc))

