        inner_cells.update(
            (rr, cc) for rr, cc in enclosed
            if any((rr + dr, cc + dc) in comp
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                   if dr or dc)
        )

        # Add a one-cell 8-neighbor halo outside the component.
        for rr, cc in comp:
            for dr in (-1, 0, 1):
