    out = [row[:] for row in grid]
    seen = set()

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != 1 or (sr, sc) in seen:
                continue

            # Get a 4-connected contour component.
            comp = set()
            stack = [(sr, sc)]
            seen.add((sr, sc))
            while stack:
                r, c = stack.pop()
                comp.add((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            rmin = min(r for r, c in comp)
            rmax = max(r for r, c in comp)
            cmin = min(c for r, c in comp)
            cmax = max(c for r, c in comp)

            # Flood the background within the component's bounding box.
            exterior = set()
            stack = []
            for r in range(rmin, rmax + 1):
                for c in (cmin, cmax):
                    if (r, c) not in comp and (r, c) not in exterior:
                        exterior.add((r, c))
                        stack.append((r, c))
            for c in range(cmin, cmax + 1):
                for r in (rmin, rmax):
                    if (r, c) not in comp and (r, c) not in exterior:
                        exterior.add((r, c))
                        stack.append((r, c))

            while stack:
                r, c = stack.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (rmin <= nr <= rmax and cmin <= nc <= cmax
                            and (nr, nc) not in comp
                            and (nr, nc) not in exterior):
                        exterior.add((nr, nc))
                        stack.append((nr, nc))

            cavity = {
                (r, c)
                for r in range(rmin, rmax + 1)
                for c in range(cmin, cmax + 1)
                if (r, c) not in comp and (r, c) not in exterior
            }
            if not cavity:
                continue

            # Mark the cavity's inner edge.
            for r, c in cavity:
                if any((r + dr, c + dc) in comp
                       for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                       if dr or dc):
                    out[r][c] = 3

            # Add the outer halo around the full contour.
            for r, c in comp:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < h and 0 <= nc < w
                                and grid[nr][nc] == 0
                                and (nr, nc) not in cavity):
                            out[nr][nc] = 2

            # Extend a halo around a contour whose bounding-box corner is
            # missing but whose adjoining side begins immediately below it.
            if rmin > 0 and cmin > 0 and (rmin + 1, cmin) in comp:
                if grid[rmin - 1][cmin - 1] == 0:
                    out[rmin - 1][cmin - 1] = 2

    return out
